def N(id, tipo, titulo, anio, ambito, evidencia, fuentes, estado="inactivo", **kw):
    d = dict(id=id, tipo=tipo, titulo=titulo, anio=anio, ambito=ambito, estado=estado, evidencia=evidencia, fuentes=fuentes)
    d.update(kw); return d

